-- Biology Ch11: The Musculoskeletal System — BATCH 3 (Fiber Types + Mechanics + Energetics + Cardiac Function)
-- 25 standalone questions. Safe to re-run: deletes only this batch's subtopics, then re-inserts.

DELETE FROM questions WHERE topic = 'The Musculoskeletal System' AND subtopic IN ('Muscle Fiber Types', 'Muscle Mechanics & Contraction Dynamics', 'Muscle Energetics & Fatigue', 'Cardiac Muscle Function');

-- Q1 [Muscle Fiber Types] easy skill1 ans=A
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'The Musculoskeletal System', 'Muscle Fiber Types', 'A histologist examines a postural muscle and notes that its slow oxidative fibers appear deep red under the microscope. This red coloration most directly reflects an abundance of a molecule that supports the fibers'' sustained, fatigue-resistant contractions by performing which function?', '[{"label": "A", "text": "Storing \\(\\text{O}_2\\) within the fiber for aerobic ATP production"}, {"label": "B", "text": "Storing glycogen for rapid anaerobic glycolysis"}, {"label": "C", "text": "Housing electron transport for oxidative phosphorylation"}, {"label": "D", "text": "Carrying \\(\\text{O}_2\\) through the bloodstream in red blood cells"}]'::jsonb, 'A', 'This is a Biology question that falls under the content category ''Organ Systems.'' The answer is A because the red color of slow oxidative fibers comes from myoglobin, an \(\text{O}_2\)-carrying molecule that stores oxygen inside the fiber to fuel aerobic ATP production. The textbook states that SO fibers "also possess myoglobin, an \(\text{O}_2\)-carrying molecule similar to \(\text{O}_2\)-carrying hemoglobin in the red blood cells. The myoglobin stores some of the needed \(\text{O}_2\) within the fibers themselves (and gives SO fibers their red color)" (lines 17826-17827), and elsewhere that "Myoglobin is found in the sarcoplasm and acts as an oxygen storage supply for the mitochondria" (lines 17872-17873). This stored oxygen, combined with abundant mitochondria and capillaries, lets SO fibers "produce large quantities of ATP, which can sustain muscle activity without fatiguing for long periods of time" (lines 17828-17829), which is why they dominate fatigue-resistant postural muscles. (Choice A) is correct: myoglobin holds an intracellular oxygen reserve that feeds aerobic respiration, and its iron-bound oxygen is precisely what makes the fiber red. (Choice B) is wrong because glycogen, not myoglobin, is the stored fuel for anaerobic glycolysis and is a hallmark of white FG fibers that "possess high amounts of glycogen, which is used in glycolysis" (lines 17845-17846); glycogen does not produce the red color. (Choice C) is wrong because, although SO fibers do contain many mitochondria that carry out oxidative phosphorylation (line 17822), the textbook attributes the red color specifically to myoglobin, not to the mitochondria themselves. (Choice D) is wrong because hemoglobin carries \(\text{O}_2\) in red blood cells within the bloodstream, whereas the molecule responsible for the fiber''s own red color is the intracellular myoglobin stored inside the fiber (line 17826); the question asks about the intracellular molecule, not the circulating one. This is a Knowledge of Scientific Concepts and Principles question because you must recall the specific function of myoglobin and why it makes slow oxidative fibers red.', 'easy', '3B', 'Organ Systems', 'biology', 1, 75)
  RETURNING id
)
